var frag=`

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;

vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,  // -1.0 + 2.0 * C.x
                        0.024390243902439); // 1.0 / 41.0
    vec2 i  = floor(v + dot(v, C.yy) );
    vec2 x0 = v -   i + dot(i, C.xx);
    vec2 i1;
    i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i); // Avoid truncation effects in permutation
    vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
        + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
    m = m*m ;
    m = m*m ;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
    vec3 g;
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
}

void main() {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    st.x *= u_resolution.x/u_resolution.y;
    vec3 color = vec3(0.0);
    vec2 pos = vec2(st*2.);

    float DF = 0.0;

    // Add a random position
    float wave = 0.0;
    float hWindNoise = snoise(vec2(1231., 56534.)+u_time*.3);
    vec2 vel = vec2(u_time*2.+hWindNoise*.2+.3, u_time*.5);
    // scale noise value from -1,1 to 0,.5
    DF += snoise(pos+vel)*.25+.25;

    // Add randomness to y sin scale
    wave = pos.y*(sin(u_time)*2.*(snoise(vec2(.2,.5)+u_time*.3)*.5+1.)+5.);

    vel = vec2(.0,wave+u_time*.2);

    // perspective
    pos *= vec2(1., pos.y*2.);

    DF += snoise(pos+vel)*.25+.25;

     DF += snoise(pos);

    // BW wave
    // color = vec3(smoothstep(.5,.6,fract(DF)));
    // // whilte holes
    // color -= vec3(smoothstep(.8,.85,fract(DF)));

    color.r = smoothstep(.4,.5,fract(DF));
    color.g = smoothstep(.5,.55,fract(DF));
    color.b = smoothstep(.5,.6,fract(DF));
    color.r -= smoothstep(.8,.85,fract(DF));
    color.g -= smoothstep(.85,.9,fract(DF));
    color.b -= smoothstep(.9,.95,fract(DF));
    color -= vec3(smoothstep(.85,.9,fract(DF)));


    gl_FragColor = vec4(1.-color,1.0);
}`
